import java.util.*;

public class main {
	public static void main(String[] all) {
		Scanner input = new Scanner(System.in);
		int t = input.nextInt();
		while (t-- > 0) {
			int n = input.nextInt();
			String num = ""+n;
			n = n % 10;
			int sum = 0;
			for (int i = 1; i < n; i++) sum += 10;
			for (int i = 1; i < num.length()+1; i++) sum += i;
			System.out.println(sum);
		}
		input.close();
	}
}
